#include <string>
using namespace std;

class Solution {
public:
    long long removeZeros(long long n) {
        string s = to_string(n);
        string res = "";
        for (char c : s) {
            if (c != '0') res += c;
        }
        return res.empty() ? 0 : stoll(res);
    }
};

class Solution {
    public long removeZeros(long n) {
        String s = Long.toString(n).replace("0", "");
        return s.isEmpty() ? 0 : Long.parseLong(s);
    }
}

var removeZeros = function(n) {
    const s = String(n).replace(/0/g, '');
    return s.length === 0 ? 0 : Number(s);
};
